// =========================================================
// Musical Fever — Router de la SPA
// Intercambia el contenido de #viewRoot sin recargar la página.
//
// Las 4 vistas (Stock, Pedidos, Historial, Nueva Nota) están
// incrustadas aquí mismo como strings (VIEWS_HTML más abajo) en
// vez de cargarse con fetch() desde views/*.html. Esto es
// intencional: fetch() de archivos locales NO funciona cuando la
// app se abre con doble clic (file:///...) — el navegador lo
// bloquea por seguridad — ni siempre de forma confiable dentro del
// WebView de Capacitor. Al incrustar el HTML directamente, la app
// funciona igual con doble clic, con Live Server, o empaquetada en
// Android con Capacitor, sin depender de un servidor.
//
// IMPORTANTE: si editas views/stock-view.html (o cualquier otra
// vista) en el futuro, ese cambio por sí solo NO se reflejará —
// hay que volver a copiar el HTML actualizado dentro del string
// correspondiente en VIEWS_HTML, más abajo en este mismo archivo.
// =========================================================

const VIEWS_HTML = {
  "stock": "<!-- ── Main: Stock ── -->\n<main class=\"main\">\n  <div class=\"topbar\">\n    <div class=\"topbar-title\">\n      <h1>Inventario / Stock</h1>\n      <p>Control de productos disponibles</p>\n    </div>\n    <div class=\"topbar-actions\">\n      <div class=\"search-wrap\">\n        <svg viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\n        <input type=\"text\" id=\"searchInput\" placeholder=\"Buscar producto o código…\" oninput=\"filterStock()\">\n      </div>\n      <button class=\"btn btn-ghost btn-select\" id=\"btnSelectMode\" onclick=\"toggleSelectionMode()\" title=\"Seleccionar varios\">\n        <svg viewBox=\"0 0 24 24\"><polyline points=\"9 11 12 14 22 4\"/><path d=\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\"/></svg>\n        <span id=\"selectModeLabel\">Seleccionar</span>\n      </button>\n      <div class=\"import-menu-wrap\" id=\"importMenuWrap\">\n        <button class=\"btn-import\" id=\"btnImportMenu\" onclick=\"toggleImportMenu(event)\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\n          Importar\n        </button>\n        <div class=\"import-menu\" id=\"importMenuDropdown\">\n          <button class=\"import-menu-item\" onclick=\"selectImportMode('full')\">\n            <strong>Importar todo</strong>\n            <span>Código, nombre, descripción, cantidad y precio — crea nuevos y actualiza existentes</span>\n          </button>\n          <button class=\"import-menu-item\" onclick=\"selectImportMode('both')\">\n            <strong>Cantidad y precio</strong>\n            <span>Suma la cantidad y reemplaza el precio en productos que ya existen</span>\n          </button>\n          <button class=\"import-menu-item\" onclick=\"selectImportMode('stock')\">\n            <strong>Solo cantidad</strong>\n            <span>Suma la cantidad al stock de productos que ya existen</span>\n          </button>\n          <button class=\"import-menu-item\" onclick=\"selectImportMode('price')\">\n            <strong>Solo precio</strong>\n            <span>Reemplaza el precio de productos que ya existen</span>\n          </button>\n        </div>\n      </div>\n      <button class=\"btn btn-ghost\" id=\"btnExportStock\" onclick=\"exportStock()\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"17 8 12 3 7 8\"/><line x1=\"12\" y1=\"3\" x2=\"12\" y2=\"15\"/></svg>\n        <span id=\"exportStockLabel\">Exportar todo</span>\n      </button>\n      <button class=\"btn btn-primary btn-new-item\" onclick=\"openModal('addModal')\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg>\n        Agregar producto\n      </button>\n    </div>\n  </div>\n\n  <div class=\"page-content\">\n\n    <!-- Stats -->\n    <div class=\"stock-stats\" id=\"stockStatsRow\">\n      <div class=\"stat-card\">\n        <div class=\"stat-label\">Total productos</div>\n        <div class=\"stat-value\" id=\"statTotal\">—</div>\n      </div>\n      <div class=\"stat-card\">\n        <div class=\"stat-label\">Stock bajo</div>\n        <div class=\"stat-value\" style=\"color:var(--red)\" id=\"statLow\">—</div>\n      </div>\n      <div class=\"stat-card\" id=\"cardValorInventario\">\n        <div class=\"stat-label\">Valor inventario</div>\n        <div class=\"stat-value\" id=\"statValue\">—</div>\n      </div>\n    </div>\n\n    <!-- Barra de acciones masivas -->\n    <div class=\"bulk-bar\" id=\"bulkBarStock\">\n      <span class=\"bulk-count\" id=\"bulkCountStock\">0 seleccionados</span>\n      <button class=\"btn-bulk-delete\" onclick=\"deleteSelectedStock()\">\n        <svg viewBox=\"0 0 24 24\" width=\"13\" height=\"13\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6\"/></svg>\n        Eliminar seleccionados\n      </button>\n      <button class=\"btn-bulk-select-all\" onclick=\"selectAllStock()\">Seleccionar todo</button>\n    </div>\n\n    <!-- Lista de productos (cards, vista mobile) -->\n    <div class=\"product-list\" id=\"productList\"></div>\n\n    <!-- Tabla de productos (vista desktop) -->\n    <div class=\"product-table-wrap\">\n      <table class=\"product-table\">\n        <thead>\n          <tr>\n            <th class=\"col-check\"><input type=\"checkbox\" class=\"row-checkbox\" id=\"checkAllStock\" onchange=\"toggleAllStock(this)\"></th>\n            <th>Código</th>\n            <th>Nombre</th>\n            <th>Descripción</th>\n            <th>Stock</th>\n            <th>Precio venta</th>\n            <th></th>\n          </tr>\n        </thead>\n        <tbody id=\"productTableBody\"></tbody>\n      </table>\n    </div>\n\n    <div class=\"empty-state\" id=\"emptyState\" style=\"display:none\">\n      <svg class=\"empty-state-icon\" viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\n      <p>Sin productos que coincidan.</p>\n    </div>\n    <div class=\"table-footer\">\n      <span class=\"table-footer-text\" id=\"footerInfo\">Cargando…</span>\n    </div>\n\n  </div>\n</main>\n\n<!-- ── Modal: Editar ── -->\n<div class=\"modal-overlay\" id=\"editModal\" onclick=\"outsideClose(event,'editModal')\">\n  <div class=\"modal\">\n    <div class=\"modal-header\">\n      <div>\n        <h2 id=\"editModalTitle\">Editar producto</h2>\n        <p id=\"editModalCode\" style=\"font-family:var(--font-mono);font-size:12px;color:var(--text-3);margin-top:3px\"></p>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeModal('editModal')\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\">\n      <div class=\"form-group\">\n        <label class=\"form-label\">Código</label>\n        <input class=\"form-input text-mono\" id=\"editCode\" type=\"text\"\n          oninput=\"this.value=this.value.toUpperCase()\" style=\"text-transform:uppercase\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Nombre del producto</label>\n        <input class=\"form-input\" id=\"editName\" type=\"text\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Descripción <span style=\"color:var(--text-3);font-weight:400;text-transform:none\">(opcional)</span></label>\n        <textarea class=\"form-input\" id=\"editDesc\" rows=\"2\" style=\"resize:vertical\" placeholder=\"Detalle adicional del producto\"></textarea>\n      </div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label class=\"form-label\">Cantidad</label>\n          <input class=\"form-input text-mono\" id=\"editStock\" type=\"number\" min=\"0\">\n        </div>\n        <div class=\"form-group\">\n          <label class=\"form-label\">Precio (S/)</label>\n          <input class=\"form-input text-mono\" id=\"editPrice\" type=\"number\" min=\"0\" step=\"0.01\">\n        </div>\n      </div>\n    </div>\n    <div class=\"modal-footer\" style=\"justify-content:space-between\">\n      <button class=\"btn btn-ghost\" id=\"btnDeleteProduct\" style=\"color:var(--red);border-color:#FECACA\" onclick=\"deleteCurrentProduct()\">Eliminar producto</button>\n      <div style=\"display:flex;gap:8px\">\n        <button class=\"btn btn-ghost\" onclick=\"closeModal('editModal')\">Cancelar</button>\n        <button class=\"btn btn-primary\" onclick=\"saveStock()\">Guardar cambios</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ── Modal: Agregar ── -->\n<div class=\"modal-overlay\" id=\"addModal\" onclick=\"outsideClose(event,'addModal')\">\n  <div class=\"modal\">\n    <div class=\"modal-header\">\n      <div>\n        <h2>Nuevo producto</h2>\n        <p style=\"font-size:12px;color:var(--text-3);margin-top:2px\">Registrar en inventario</p>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeModal('addModal')\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\">\n      <div class=\"form-group\">\n        <label class=\"form-label\">Código</label>\n        <input class=\"form-input text-mono\" id=\"addCode\" type=\"text\" placeholder=\"GTR-006\"\n          oninput=\"this.value=this.value.toUpperCase()\" style=\"text-transform:uppercase\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Nombre del producto</label>\n        <input class=\"form-input\" id=\"addName\" type=\"text\" placeholder=\"Ej: Guitarra Yamaha C40\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Descripción <span style=\"color:var(--text-3);font-weight:400;text-transform:none\">(opcional)</span></label>\n        <textarea class=\"form-input\" id=\"addDesc\" rows=\"2\" style=\"resize:vertical\" placeholder=\"Detalle adicional del producto\"></textarea>\n      </div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label class=\"form-label\">Cantidad</label>\n          <input class=\"form-input text-mono\" id=\"addStock\" type=\"number\" min=\"0\" placeholder=\"0\">\n        </div>\n        <div class=\"form-group\">\n          <label class=\"form-label\">Precio (S/)</label>\n          <input class=\"form-input text-mono\" id=\"addPrice\" type=\"number\" min=\"0\" step=\"0.01\" placeholder=\"0.00\">\n        </div>\n      </div>\n    </div>\n    <div class=\"modal-footer\">\n      <button class=\"btn btn-ghost\" onclick=\"closeModal('addModal')\">Cancelar</button>\n      <button class=\"btn btn-primary\" onclick=\"addProduct()\">Registrar producto</button>\n    </div>\n  </div>\n</div>\n\n<!-- ── Modal: Importar stock ── -->\n<div class=\"modal-overlay\" id=\"importStockModal\" onclick=\"if(event.target===this)closeImportStock()\">\n  <div class=\"modal import-modal\">\n    <div class=\"modal-header\">\n      <div>\n        <h2 id=\"importStockModalTitle\">Importar productos</h2>\n        <p id=\"importStockModalHint\" style=\"font-size:12px;color:var(--text-3);margin-top:3px\"></p>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeImportStock()\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\">\n\n      <!-- Paso 1 -->\n      <div id=\"stepUploadStock\">\n        <div class=\"import-template-bar\">\n          <span>¿Primera vez? Descarga la plantilla con el formato correcto para esta opción.</span>\n          <button class=\"btn-template\" onclick=\"downloadStockTemplate()\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\n            Descargar plantilla\n          </button>\n        </div>\n        <label class=\"import-drop-area\" for=\"importStockFile\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"17 8 12 3 7 8\"/><line x1=\"12\" y1=\"3\" x2=\"12\" y2=\"15\"/></svg>\n          <p>Arrastra tu archivo aquí o <strong>haz clic para seleccionar</strong></p>\n          <p style=\"margin-top:6px;font-size:11.5px\" id=\"importStockDropHint\">Excel (.xlsx) o CSV</p>\n        </label>\n        <input type=\"file\" id=\"importStockFile\" class=\"import-file-input\"\n          accept=\".xlsx,.xls,.csv\" onchange=\"onImportStockFile(this)\">\n        <div id=\"importStockError\" style=\"display:none;margin-top:12px;padding:10px 14px;background:var(--red-bg);border:1px solid #FECACA;border-radius:var(--r-sm);font-size:12.5px;color:var(--red)\"></div>\n      </div>\n\n      <!-- Paso 2: Preview -->\n      <div id=\"stepPreviewStock\" style=\"display:none\">\n        <p class=\"import-summary\" id=\"previewStockSummary\"></p>\n        <p id=\"previewStockSanitizedWarning\" style=\"display:none;margin:0 0 10px;padding:8px 12px;background:var(--yellow-bg,#FEF3C7);border:1px solid #FDE68A;border-radius:var(--r-sm);font-size:12px;color:#92400E\"></p>\n        <div class=\"import-preview-wrap\">\n          <div id=\"previewStockBody\"></div>\n        </div>\n      </div>\n\n      <!-- Paso 3: Conflictos de código (solo si hay) -->\n      <div id=\"stepConflictStock\" style=\"display:none\">\n        <p class=\"import-summary\" id=\"conflictStockSummary\"></p>\n        <p id=\"conflictStockExplain\" style=\"display:none;margin:0 0 12px;padding:10px 14px;background:#FEE2E2;border:1px solid #FECACA;border-radius:var(--r-sm);font-size:12.5px;color:#7F1D1D;line-height:1.5\"></p>\n        <div id=\"conflictStockBody\"></div>\n      </div>\n\n      <!-- Paso 4: Listo -->\n      <div id=\"stepDoneStock\" style=\"display:none\">\n        <div class=\"import-done\">\n          <div class=\"import-done-icon\"><svg viewBox=\"0 0 24 24\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\n          <p id=\"importStockDoneMsg\"></p>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"modal-footer\">\n      <button class=\"btn btn-ghost\" id=\"btnCerrarImportStock\" onclick=\"closeImportStock()\">Cerrar</button>\n      <button class=\"btn btn-primary\" id=\"btnSiguienteImportStock\" onclick=\"goToConflictStep()\" style=\"display:none\">Siguiente</button>\n      <button class=\"btn btn-primary\" id=\"btnProcesarImportStock\" onclick=\"processImportStock()\" style=\"display:none\">Procesar importación</button>\n    </div>\n  </div>\n</div>\n",
  "pedidos": "<!-- ── Main: Notas de Pedido ── -->\n<main class=\"main\">\n  <div class=\"topbar\">\n    <div class=\"topbar-title\">\n      <h1>Notas de Pedido</h1>\n      <p>Gestión de órdenes de clientes</p>\n    </div>\n    <div class=\"topbar-actions\">\n      <div class=\"search-wrap\">\n        <svg viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\n        <input type=\"text\" id=\"searchInput\" placeholder=\"RUC o razón social…\" oninput=\"filterTable()\">\n      </div>\n      <button class=\"btn btn-ghost btn-select\" id=\"btnSelectMode\" onclick=\"toggleClienteSelectionMode()\" title=\"Seleccionar varios\">\n        <svg viewBox=\"0 0 24 24\"><polyline points=\"9 11 12 14 22 4\"/><path d=\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\"/></svg>\n        <span id=\"selectModeLabel\">Seleccionar</span>\n      </button>\n      <button class=\"btn-import\" onclick=\"openImportClientes()\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\n        Importar\n      </button>\n      <button class=\"btn btn-ghost\" id=\"btnExportClientes\" onclick=\"exportClientes()\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"17 8 12 3 7 8\"/><line x1=\"12\" y1=\"3\" x2=\"12\" y2=\"15\"/></svg>\n        <span id=\"exportClientesLabel\">Exportar todo</span>\n      </button>\n      <button class=\"btn btn-ghost btn-new-item\" onclick=\"openNewClient()\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><line x1=\"19\" y1=\"8\" x2=\"19\" y2=\"14\"/><line x1=\"22\" y1=\"11\" x2=\"16\" y2=\"11\"/></svg>\n        Nuevo cliente\n      </button>\n    </div>\n  </div>\n\n  <div class=\"page-content\">\n    <!-- Barra de acciones masivas -->\n    <div class=\"bulk-bar\" id=\"bulkBarClientes\">\n      <span class=\"bulk-count\" id=\"bulkCountClientes\">0 seleccionados</span>\n      <button class=\"btn-bulk-delete\" onclick=\"deleteSelectedClientes()\">\n        <svg viewBox=\"0 0 24 24\" width=\"13\" height=\"13\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6\"/></svg>\n        Eliminar seleccionados\n      </button>\n      <button class=\"btn-bulk-select-all\" onclick=\"selectAllClientes()\">Seleccionar todo</button>\n    </div>\n\n    <div class=\"table-wrap\">\n      <div class=\"table-footer table-footer-top\">\n        <span class=\"table-footer-text\" id=\"footerInfo\">Cargando…</span>\n      </div>\n      <table>\n        <thead>\n          <tr>\n            <th class=\"col-check\"><input type=\"checkbox\" class=\"row-checkbox\" id=\"checkAllClientes\" onchange=\"toggleAllClientes(this)\"></th>\n            <th class=\"col-ruc\">RUC</th>\n            <th>Cliente</th>\n            <th class=\"col-city\">Ciudad</th>\n            <th class=\"col-acts\">Acciones</th>\n          </tr>\n        </thead>\n        <tbody id=\"tableBody\">\n        </tbody>\n      </table>\n      <div class=\"empty-state\" id=\"emptyState\">\n        <svg class=\"empty-state-icon\" viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\n        <p>Sin resultados para esa búsqueda.</p>\n      </div>\n    </div>\n  </div>\n</main>\n\n<!-- ── Modal: Editar cliente ─── -->\n<div class=\"modal-overlay\" id=\"editModal\" onclick=\"outsideCloseCliente(event)\">\n  <div class=\"modal\">\n    <div class=\"modal-header\">\n      <div>\n        <h2 id=\"editModalTitle\">Editar cliente</h2>\n        <p style=\"font-size:12px;color:var(--text-3);margin-top:2px\" id=\"editModalSubtitle\">Modificar datos del cliente en la nota</p>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeEdit()\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\">\n      <div class=\"modal-detail-row\" id=\"editCurrentInfo\">\n        <div class=\"modal-detail-item\">\n          <div class=\"modal-detail-label\">RUC actual</div>\n          <div class=\"modal-detail-value\" id=\"editCurrentRuc\">—</div>\n        </div>\n        <div class=\"modal-detail-item\">\n          <div class=\"modal-detail-label\">Ciudad</div>\n          <div class=\"modal-detail-value\" id=\"editCurrentCity\">—</div>\n        </div>\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">RUC</label>\n        <input class=\"form-input text-mono\" id=\"editRuc\" type=\"text\" maxlength=\"11\" placeholder=\"20xxxxxxxxx\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Razón social</label>\n        <input class=\"form-input\" id=\"editNombre\" type=\"text\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Ciudad <span style=\"color:var(--text-3);font-weight:400;text-transform:none\">(opcional)</span></label>\n        <input class=\"form-input\" id=\"editCiudad\" type=\"text\">\n      </div>\n    </div>\n    <div class=\"modal-footer\" style=\"justify-content:space-between\">\n      <button class=\"btn btn-ghost\" id=\"btnDeleteClient\" style=\"color:var(--red);border-color:#FECACA\" onclick=\"deleteCurrentClient()\">Eliminar cliente</button>\n      <div style=\"display:flex;gap:8px\">\n        <button class=\"btn btn-ghost\" onclick=\"closeEdit()\">Cancelar</button>\n        <button class=\"btn btn-primary\" onclick=\"saveEdit()\">Guardar cambios</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ── Modal: Importar clientes ── -->\n<div class=\"modal-overlay\" id=\"importClientesModal\" onclick=\"if(event.target===this)closeImportClientes()\">\n  <div class=\"modal import-modal\">\n    <div class=\"modal-header\">\n      <h2>Importar clientes</h2>\n      <button class=\"modal-close\" onclick=\"closeImportClientes()\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\">\n\n      <!-- Paso 1: Subir archivo -->\n      <div id=\"stepUpload\">\n        <div class=\"import-template-bar\">\n          <span>¿Primera vez? Descarga la plantilla oficial con el formato correcto.</span>\n          <button class=\"btn-template\" onclick=\"downloadClientTemplate()\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\n            Descargar plantilla\n          </button>\n        </div>\n        <label class=\"import-drop-area\" for=\"importClientesFile\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"17 8 12 3 7 8\"/><line x1=\"12\" y1=\"3\" x2=\"12\" y2=\"15\"/></svg>\n          <p>Arrastra tu archivo aquí o <strong>haz clic para seleccionar</strong></p>\n          <p style=\"margin-top:6px;font-size:11.5px\">Excel (.xlsx) o CSV</p>\n        </label>\n        <input type=\"file\" id=\"importClientesFile\" class=\"import-file-input\"\n          accept=\".xlsx,.xls,.csv\" onchange=\"onImportClientesFile(this)\">\n        <div id=\"importClientesError\" style=\"display:none;margin-top:12px;padding:10px 14px;background:var(--red-bg);border:1px solid #FECACA;border-radius:var(--r-sm);font-size:12.5px;color:var(--red)\"></div>\n      </div>\n\n      <!-- Paso 2: Vista previa -->\n      <div id=\"stepPreview\" style=\"display:none\">\n        <p class=\"import-summary\" id=\"previewClientesSummary\"></p>\n        <div class=\"import-preview-wrap\">\n          <div id=\"previewClientesBody\"></div>\n        </div>\n      </div>\n\n      <!-- Paso 3: Duplicados -->\n      <div id=\"stepDuplicates\" style=\"display:none\">\n        <p class=\"import-summary\" id=\"dupClientesSummary\"></p>\n        <div class=\"import-preview-wrap\">\n          <div id=\"dupClientesListBody\"></div>\n        </div>\n        <div class=\"dup-bulk-actions\">\n          <button class=\"btn-dup-cancel\" onclick=\"resolveDuplicate('cancelar')\">Cancelar importación</button>\n          <button class=\"btn-dup-omit-all\" onclick=\"resolveDuplicate('omitir')\">Omitir duplicados e importar el resto</button>\n        </div>\n      </div>\n\n      <!-- Paso 4: Listo -->\n      <div id=\"stepDone\" style=\"display:none\">\n        <div class=\"import-done\">\n          <div class=\"import-done-icon\"><svg viewBox=\"0 0 24 24\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\n          <p id=\"importDoneMsg\"></p>\n        </div>\n      </div>\n\n    </div>\n    <div class=\"modal-footer\">\n      <button class=\"btn btn-ghost\" onclick=\"closeImportClientes()\">Cerrar</button>\n      <button class=\"btn btn-primary\" id=\"btnProcesarImport\"\n        onclick=\"processImportClientes()\"\n        style=\"display:none\">Procesar importación</button>\n    </div>\n  </div>\n</div>\n",
  "historial": "<style>\n\n  .hist-meta { display: flex; align-items: center; gap: 8px; margin-bottom: 18px; }\n\n  .col-num   { width: 130px; }\n  .col-vendedor { width: 120px; }\n  .col-date  { width: 110px; }\n  .col-total { width: 120px; text-align: right; }\n  .col-act   { width: 90px; text-align: right; }\n\n  .nota-num {\n    font-family: var(--font-mono); font-size: 12.5px;\n    font-weight: 600; color: var(--accent);\n  }\n  .client-hist { font-size: 13.5px; font-weight: 600; color: var(--text-1); }\n  .ruc-hist    { font-size: 11.5px; color: var(--text-3); font-family: var(--font-mono); margin-top: 1px; }\n  .date-hist   { font-size: 12.5px; color: var(--text-3); font-family: var(--font-mono); }\n  .total-hist  { font-family: var(--font-mono); font-size: 13px; font-weight: 600; color: var(--text-1); text-align: right; }\n\n  /* ── Tarjeta de historial en móvil: diseño propio, compacto y estructurado ── */\n  .hist-card-mobile { display: none; }\n\n  @media (max-width: 768px) {\n    #histBody tr {\n      display: block;\n      background: var(--surface);\n      border: 1px solid var(--border);\n      border-radius: var(--r);\n      box-shadow: var(--shadow-sm);\n      padding: 0;\n      margin-bottom: 10px;\n      overflow: hidden;\n    }\n    #histBody tr:last-child { margin-bottom: 0; }\n\n    /* Oculta las celdas normales de escritorio, muestra solo la tarjeta */\n    #histBody td { display: none; }\n    #histBody td.hist-card-mobile { display: block !important; padding: 13px 14px; }\n\n    .hist-card-top {\n      display: flex; align-items: center; justify-content: space-between;\n      margin-bottom: 9px;\n    }\n    .hist-card-num {\n      font-family: var(--font-mono); font-size: 12.5px; font-weight: 700;\n      color: var(--accent);\n    }\n    .hist-card-total {\n      font-family: var(--font-mono); font-size: 14px; font-weight: 700;\n      color: var(--text-1); letter-spacing: -0.01em;\n    }\n    .hist-card-client { font-size: 13.5px; font-weight: 600; color: var(--text-1); text-align: left; }\n    .hist-card-ruc {\n      font-size: 11px; color: var(--text-3); font-family: var(--font-mono);\n      margin-top: 1px; margin-bottom: 11px; text-align: left;\n    }\n    .hist-card-bottom {\n      display: flex; align-items: center; justify-content: space-between;\n      padding-top: 10px; border-top: 1px solid var(--border);\n    }\n    .hist-card-date { font-size: 11.5px; color: var(--text-3); font-family: var(--font-mono); }\n    .hist-card-btn {\n      height: 30px; padding: 0 14px; font-size: 12px;\n      background: var(--accent); color: white; border-color: var(--accent);\n      font-weight: 600;\n    }\n  }\n\n  /* Stats strip */\n  .hist-stats {\n    display: grid; grid-template-columns: repeat(2, 1fr);\n    gap: 14px; margin-bottom: 20px;\n  }\n  .hstat {\n    background: var(--surface); border: 1px solid var(--border);\n    border-radius: var(--r); padding: 14px 16px;\n    box-shadow: var(--shadow-sm);\n  }\n  .hstat-label { font-size: 10.5px; font-weight: 600; color: var(--text-3); text-transform: uppercase; letter-spacing: 0.08em; }\n  .hstat-value { font-size: 22px; font-weight: 700; color: var(--text-1); letter-spacing: -0.03em; margin-top: 3px; font-family: var(--font-mono); }\n\n  /* En móvil, mientras el buscador tiene el foco (teclado abierto),\n     se ocultan las tarjetas de stats y la barra de navegación inferior\n     para dejar más espacio visible a los resultados de la búsqueda. */\n  @media (max-width: 768px) {\n    body.search-focused .hist-stats { display: none; }\n    body.search-focused .sidebar    { display: none !important; }\n  }\n\n  /* ── Filtro rápido por fecha (Hoy/Semana/Quincena/Mes) ──\n     Ícono junto a \"Limpiar\". El menú flota con position:absolute\n     para no desplazar ni tapar el resto de la barra de filtros. */\n  .quick-range-wrap { position: relative; align-self: flex-end; }\n  .quick-range-btn {\n    height: 34px; width: 34px; padding: 0;\n    display: inline-flex; align-items: center; justify-content: center;\n  }\n  .quick-range-btn svg { fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }\n  .quick-range-menu {\n    display: none;\n    position: absolute; top: calc(100% + 6px); right: 0; z-index: 30;\n    background: var(--surface); border: 1px solid var(--border);\n    border-radius: var(--r-sm); box-shadow: var(--shadow-md, 0 8px 20px rgba(0,0,0,.12));\n    padding: 6px; min-width: 130px;\n  }\n  .quick-range-menu.open { display: flex; flex-direction: column; gap: 2px; }\n  .quick-range-menu button {\n    text-align: left; border: none; background: none; cursor: pointer;\n    padding: 8px 10px; font-size: 13px; color: var(--text-1);\n    border-radius: 6px; font-family: inherit;\n  }\n  .quick-range-menu button:hover { background: var(--surface-2); }\n\n  /* ── Placeholder visual \"dd/mm/aaaa\" para los inputs de fecha ──\n     Algunos WebViews de Android no pintan el patrón nativo del\n     input type=\"date\" cuando está vacío, así que se superpone un\n     texto guía que se oculta apenas el campo tiene una fecha. */\n  .date-field-wrap { position: relative; }\n  .date-placeholder {\n    position: absolute; left: 12px; top: 50%; transform: translateY(-50%);\n    font-size: 13px; color: var(--text-3); pointer-events: none;\n  }\n  .date-field-wrap input.has-value + .date-placeholder { display: none; }\n\n  /* ── Vista de nota completa (idéntica al export de imagen) ── */\n  .ver-modal-content { background: white; }\n  .print-header { display: flex; justify-content: space-between; margin-bottom: 18px; align-items: flex-start; }\n  .print-meta { text-align: right; font-size: 12px; color: #64748b; line-height: 1.5; }\n  .print-meta strong { color: #0B1120; font-size: 13.5px; display: block; margin-bottom: 2px; }\n  .print-client-box { background: #F7F9FC; border-radius: 8px; padding: 12px 16px; margin-bottom: 16px; }\n  .print-client-box .label { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.07em; color: #94a3b8; margin-bottom: 3px; }\n  .print-client-box .val { font-size: 13px; font-weight: 700; color: #0B1120; line-height: 1.3; }\n  .print-client-box .ruc { font-size: 11.5px; color: #64748b; font-family: 'DM Mono', monospace; margin-top: 2px; }\n  .ver-modal-content { overflow-x: hidden; }\n  .print-table { width: 100%; table-layout: fixed; border-collapse: collapse; margin-bottom: 14px; }\n  .print-table th { background: #F0F3F9; padding: 8px 8px; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; color: #64748b; text-align: left; border-bottom: 2px solid #E2E8F4; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  .print-table th.right, .print-table td.right { text-align: right; }\n  .print-table td { padding: 9px 8px; border-bottom: 1px solid #E2E8F4; font-size: 12.5px; color: #0B1120; overflow-wrap: break-word; word-break: break-word; }\n  .print-table td[data-label=\"Producto\"] { white-space: normal; }\n  .print-table td.right { white-space: nowrap; }\n  .print-table th:nth-child(1), .print-table td:nth-child(1) { width: 14%; }\n  .print-table th:nth-child(2), .print-table td:nth-child(2) { width: 30%; }\n  .print-table th:nth-child(3), .print-table td:nth-child(3) { width: 16%; }\n  .print-table th:nth-child(4), .print-table td:nth-child(4) { width: 10%; }\n  .print-table th:nth-child(5), .print-table td:nth-child(5) { width: 12%; }\n  .print-table th:nth-child(6), .print-table td:nth-child(6) { width: 18%; }\n  .print-totals { margin-left: auto; width: 260px; }\n  .print-total-row { display: flex; justify-content: space-between; padding: 6px 0; font-size: 12.5px; color: #64748b; border-bottom: 1px solid #E2E8F4; }\n  .print-total-row.final { font-weight: 700; font-size: 14.5px; color: #0B1120; border-bottom: none; padding-top: 10px; }\n  .print-footer { margin-top: 20px; text-align: center; font-size: 10.5px; color: #94a3b8; }\n  .print-state-badge { margin-top: 6px; }\n\n  /* ── Footer del modal de detalle de nota: Cerrar a la izquierda\n     (pequeño), Compartir/Descargar agrupados a la derecha, con\n     aire respecto al borde inferior del modal ── */\n  .ver-modal-footer {\n    display: flex; align-items: center; justify-content: space-between;\n    padding: 14px 20px 22px;\n  }\n  .btn-sm { height: 32px; padding: 0 14px; font-size: 12.5px; }\n  .ver-modal-actions { display: flex; gap: 8px; align-items: flex-start; }\n\n  /* En escritorio no se muestra el botón Cerrar del footer: ya existe\n     la X en la esquina superior del modal para cerrar. Solo se conserva\n     como link discreto en móvil (ver media query de abajo). */\n  @media (min-width: 769px) {\n    .ver-modal-footer > .btn-sm { display: none; }\n  }\n\n  /* Móvil: acciones arriba, Cerrar debajo como link discreto */\n  @media (max-width: 768px) {\n    .ver-modal-footer {\n      flex-direction: column-reverse;\n      align-items: stretch;\n      gap: 0;\n      padding: 12px 16px 16px;\n    }\n    .ver-modal-actions {\n      justify-content: stretch;\n      width: 100%;\n      margin-bottom: 0;\n    }\n    .ver-modal-actions .download-menu-wrap,\n    .ver-modal-actions .download-menu-wrap .btn {\n      flex: 1; width: 100%;\n    }\n    /* Eliminar/Editar/Compartir: solo icono en móvil para ahorrar espacio */\n    .ver-modal-actions .btn.btn-icon-mobile {\n      flex: 0 0 auto; width: 40px; height: 40px;\n      padding: 0; display: inline-flex;\n      align-items: center; justify-content: center;\n    }\n    .ver-modal-actions .btn.btn-icon-mobile .btn-label { display: none; }\n    /* Cerrar: link discreto centrado, sin borde ni fondo */\n    .ver-modal-footer > .btn-sm {\n      width: 100%; justify-content: center;\n      background: none !important; border: none !important;\n      box-shadow: none !important;\n      color: var(--text-3); font-size: 13px; font-weight: 500;\n      padding: 12px 0 0;\n      height: auto;\n    }\n    .ver-modal-footer > .btn-sm:active { color: var(--text-2); }\n  }\n\n  .download-menu-wrap { position: relative; }\n  .download-menu {\n    display: none;\n    position: absolute; right: 0; bottom: calc(100% + 6px);\n    background: var(--surface); border: 1px solid var(--border);\n    border-radius: var(--r); box-shadow: var(--shadow-lg);\n    padding: 4px; min-width: 120px; z-index: 200;\n  }\n  .download-menu.open { display: block; }\n  .download-menu-item {\n    display: block; width: 100%;\n    padding: 9px 14px; border-radius: var(--r-sm);\n    background: none; border: none; cursor: pointer; text-align: left;\n    font-size: 13.5px; font-weight: 500; color: var(--text-1);\n    font-family: inherit;\n    transition: background var(--t);\n  }\n  .download-menu-item:hover { background: var(--surface-2); }\n  #btnDownloadNota .chev { width: 13px; height: 13px; margin-left: 2px; }\n\n  /* ── Responsive: modal de detalle de nota en móvil ── */\n  /* La tabla de productos SIEMPRE se muestra como tabla con columnas,\n     incluso en pantallas pequeñas, para que la imagen compartida/descargada\n     se vea idéntica sin importar el dispositivo. table-layout:fixed +\n     anchos en % garantizan que ninguna columna se corte ni aparezca scroll. */\n  @media (max-width: 768px) {\n    .modal-body[style] { padding: 10px !important; }\n    .ver-modal-content[style] { padding: 12px !important; }\n    .print-header { flex-direction: column; gap: 10px; align-items: flex-start; }\n    .print-meta { text-align: left; }\n    .print-totals { width: 100%; margin-left: 0; }\n\n    .print-table { font-size: 10px; table-layout: fixed; width: 100%; }\n    .print-table th { padding: 6px 3px; font-size: 7.5px; letter-spacing: 0.02em; overflow: hidden; }\n    .print-table td { padding: 6px 3px; font-size: 9.5px; overflow: hidden; }\n    .print-table td[data-label=\"Producto\"] { white-space: normal; line-height: 1.25; word-break: break-word; }\n    .print-table td.right { white-space: nowrap; }\n    .print-table .curr { display: none; }\n    .print-table th:nth-child(1), .print-table td:nth-child(1) { width: 13%; overflow-wrap: break-word; }\n    .print-table th:nth-child(2), .print-table td:nth-child(2) { width: 28%; }\n    .print-table th:nth-child(3), .print-table td:nth-child(3) { width: 18%; }\n    .print-table th:nth-child(4), .print-table td:nth-child(4) { width: 10%; }\n    .print-table th:nth-child(5), .print-table td:nth-child(5) { width: 13%; }\n    .print-table th:nth-child(6), .print-table td:nth-child(6) { width: 18%; }\n  }\n\n\n  /* ── MOBILE IMPROVEMENTS ── */\n  @media (max-width: 768px) {\n    /* Botón \"Ver\" → azul primario en tarjetas */\n    .table-wrap td[data-label=\"\"] .btn {\n      background: var(--accent) !important;\n      color: white !important;\n      border-color: var(--accent) !important;\n      font-weight: 600 !important;\n    }\n    .print-header { flex-direction: column; gap: 10px; }\n    .print-meta { text-align: left; }\n    .print-totals { width: 100%; margin-left: 0; }\n\n    /* Buscador + botón \"más filtros\" en una sola fila compacta.\n       Fechas, filtro rápido, Limpiar, Seleccionar y Exportar Excel\n       quedan plegados dentro de .filter-extra hasta que se toque\n       el botón — antes ocupaban ~430px siempre visibles. */\n    .filter-bar { padding: 10px 12px; gap: 8px; }\n    .filter-search-row { min-width: 0; }\n    .filter-search-inline { display: flex; gap: 6px; align-items: center; }\n    .filter-search-inline .filter-input { flex: 1; }\n    .filter-toggle-btn {\n      flex: 0 0 auto; width: 34px; height: 34px;\n      display: flex; align-items: center; justify-content: center;\n      border: 1px solid var(--border); border-radius: var(--r-sm);\n      background: var(--surface); color: var(--text-2);\n    }\n    .filter-toggle-btn.active {\n      background: var(--accent-soft, rgba(37,99,235,0.08));\n      border-color: var(--accent); color: var(--accent);\n    }\n    .filter-extra {\n      display: none;\n      flex-wrap: wrap; gap: 10px; align-items: flex-end;\n      margin-top: 10px; padding-top: 10px;\n      border-top: 1px solid var(--border);\n    }\n    .filter-extra.open { display: flex; }\n    .filter-extra .export-bar {\n      width: 100%; margin: 0; padding-top: 4px;\n    }\n\n    /* Estadísticas: chips en fila horizontal en vez de tarjetas\n       apiladas — mismo dato, mucho menos alto. */\n    .hist-stats {\n      display: flex; grid-template-columns: none;\n      gap: 8px; overflow-x: auto; margin-bottom: 14px;\n      -webkit-overflow-scrolling: touch;\n    }\n    .hstat {\n      flex: 0 0 auto; min-width: 92px;\n      padding: 8px 12px; border-left-width: 3px;\n    }\n    .hstat-value { font-size: 16px; margin-top: 1px; }\n    .hstat-label { font-size: 9px; }\n\n    .client-hist { font-size: 13.5px; }\n    .nota-num { font-size: 12.5px; }\n    .total-hist { font-size: 13px; }\n  }\n\n  /* En escritorio el panel de fechas/exportar siempre está visible\n     y el botón de alternar (solo tiene sentido en móvil) se oculta. */\n  @media (min-width: 769px) {\n    .filter-toggle-btn { display: none; }\n    .filter-extra { display: flex !important; }\n    .filter-search-inline { display: contents; }\n  }\n\n\n  /* ── Barra de filtros ── */\n  .filter-bar {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 10px;\n    align-items: flex-end;\n    padding: 14px 16px;\n    background: var(--surface);\n    border: 1px solid var(--border);\n    border-radius: var(--r);\n    box-shadow: var(--shadow-sm);\n    margin-bottom: 18px;\n  }\n  .filter-group {\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n    flex: 1;\n    min-width: 140px;\n  }\n  .filter-label {\n    font-size: 10px;\n    font-weight: 700;\n    text-transform: uppercase;\n    letter-spacing: .07em;\n    color: var(--text-3);\n  }\n  .filter-input {\n    height: 34px;\n    border: 1px solid var(--border);\n    border-radius: var(--r-sm);\n    padding: 0 10px;\n    font-size: 13px;\n    font-family: var(--font-ui);\n    color: var(--text-1);\n    background: var(--surface-2);\n    outline: none;\n    transition: border-color var(--t);\n  }\n  .filter-input:focus { border-color: var(--accent); }\n  .filter-actions { display: flex; gap: 8px; align-items: flex-end; }\n\n  /* ── Stat adicional de ingresos ── */\n  .hist-stats { grid-template-columns: repeat(3, 1fr); }\n  @media (max-width: 600px) { .hist-stats { grid-template-columns: repeat(2, 1fr); } }\n\n  /* ── Toast limpieza ── */\n  #cleanupToast {\n    display: none;\n    position: fixed;\n    bottom: 20px;\n    left: 50%;\n    transform: translateX(-50%);\n    background: var(--text-1);\n    color: #fff;\n    padding: 10px 18px;\n    border-radius: var(--r);\n    font-size: 13px;\n    font-weight: 500;\n    z-index: 9999;\n    box-shadow: var(--shadow-lg);\n  }\n\n  /* ── Botones de exportar ── */\n  .export-bar {\n    display: flex;\n    gap: 8px;\n    margin-bottom: 12px;\n    flex-wrap: wrap;\n  }\n\n  /* Nota number: azul como en la imagen */\n  .nota-num, .hist-card-num { color: #2E5BBA !important; font-family: var(--font-mono); font-weight: 600; }\n  /* Stat cards: borde rojo izquierdo */\n  .hstat {\n    border-left: 3px solid var(--accent) !important;\n  }\n  /* Historial cards borde rojo */\n  .hist-card {\n    border-left: 3px solid var(--accent) !important;\n  }\n  /* Ver detalle button: azul marino */\n  .btn-ver-detalle {\n    background: var(--ink); color: #fff; border: none;\n    border-radius: var(--r-sm); padding: 0 14px; height: 32px;\n    font-size: 12.5px; font-weight: 600; cursor: pointer;\n    font-family: var(--font-ui); transition: background var(--t);\n  }\n  .btn-ver-detalle:hover { background: var(--ink-hover); }\n  /* Filter bar inputs: light style */\n  .filter-input {\n    background: var(--surface) !important;\n    border: 1px solid var(--border) !important;\n    color: var(--text-1) !important;\n  }\n</style>\n\n<main class=\"main\">\n  <div class=\"topbar\">\n    <div class=\"topbar-title\">\n      <h1>Historial de Pedidos</h1>\n      <p>Registro completo de notas emitidas</p>\n    </div>\n  </div>\n\n  <div class=\"page-content\">\n\n    <!-- ── Filtros ── -->\n    <div class=\"filter-bar\">\n      <div class=\"filter-group filter-search-row\">\n        <label class=\"filter-label\">Buscar (cliente / nota / RUC)</label>\n        <div class=\"filter-search-inline\">\n          <input class=\"filter-input\" type=\"text\" id=\"searchInput\" placeholder=\"Nombre, NP-2026-001 o RUC...\" oninput=\"limitSearchInput(this); applyFilters()\" onfocus=\"document.body.classList.add('search-focused')\" onblur=\"document.body.classList.remove('search-focused')\">\n          <button class=\"filter-toggle-btn\" id=\"filterToggleBtn\" onclick=\"toggleFilterExtra()\" title=\"Más filtros\" type=\"button\" aria-expanded=\"false\">\n            <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"4\" y1=\"6\" x2=\"20\" y2=\"6\"/><line x1=\"4\" y1=\"12\" x2=\"20\" y2=\"12\"/><line x1=\"4\" y1=\"18\" x2=\"20\" y2=\"18\"/><circle cx=\"9\" cy=\"6\" r=\"1.5\" fill=\"currentColor\" stroke=\"none\"/><circle cx=\"16\" cy=\"12\" r=\"1.5\" fill=\"currentColor\" stroke=\"none\"/><circle cx=\"11\" cy=\"18\" r=\"1.5\" fill=\"currentColor\" stroke=\"none\"/></svg>\n          </button>\n        </div>\n      </div>\n\n      <div class=\"filter-extra\" id=\"filterExtra\">\n        <div class=\"filter-group\" style=\"min-width:130px;max-width:160px\">\n          <label class=\"filter-label\">Desde</label>\n          <div class=\"date-field-wrap\">\n            <input class=\"filter-input\" type=\"date\" id=\"filterDesde\" onchange=\"applyFilters(); toggleDatePlaceholder(this)\">\n            <span class=\"date-placeholder\" id=\"phDesde\">dd/mm/aaaa</span>\n          </div>\n        </div>\n        <div class=\"filter-group\" style=\"min-width:130px;max-width:160px\">\n          <label class=\"filter-label\">Hasta</label>\n          <div class=\"date-field-wrap\">\n            <input class=\"filter-input\" type=\"date\" id=\"filterHasta\" onchange=\"applyFilters(); toggleDatePlaceholder(this)\">\n            <span class=\"date-placeholder\" id=\"phHasta\">dd/mm/aaaa</span>\n          </div>\n        </div>\n        <div class=\"filter-group\" style=\"min-width:150px;max-width:190px\">\n          <label class=\"filter-label\">Vendedor</label>\n          <select class=\"filter-input\" id=\"filterVendedor\" onchange=\"applyFilters()\">\n            <option value=\"\">Todos (general)</option>\n          </select>\n        </div>\n        <div class=\"quick-range-wrap\">\n          <button class=\"btn btn-ghost quick-range-btn\" id=\"quickRangeBtn\" onclick=\"toggleQuickRange(event)\" title=\"Filtro rápido por fecha\" type=\"button\">\n            <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\"><polygon points=\"22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3\"/></svg>\n          </button>\n          <div class=\"quick-range-menu\" id=\"quickRangeMenu\">\n            <button type=\"button\" onclick=\"applyQuickRange('hoy')\">Hoy</button>\n            <button type=\"button\" onclick=\"applyQuickRange('semana')\">Semana</button>\n            <button type=\"button\" onclick=\"applyQuickRange('quincena')\">Quincena</button>\n            <button type=\"button\" onclick=\"applyQuickRange('mes')\">Mes</button>\n          </div>\n        </div>\n        <div class=\"filter-actions\">\n          <button class=\"btn btn-ghost\" onclick=\"clearFilters()\" style=\"height:34px;font-size:12px;padding:0 12px\">\n            <svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n            Limpiar\n          </button>\n        </div>\n\n        <!-- ── Exportar / Seleccionar (admin y vendedor; \"Seleccionar\" se\n             oculta para vendedor vía applyHistorialRoleRestrictions) ── -->\n        <div class=\"export-bar\">\n          <button class=\"btn btn-ghost btn-select\" id=\"btnSelectMode\" onclick=\"toggleHistSelectionMode()\" style=\"font-size:12px;height:32px;padding:0 12px\">\n            <svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\"><polyline points=\"9 11 12 14 22 4\"/><path d=\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\"/></svg>\n            <span id=\"selectModeLabel\">Seleccionar</span>\n          </button>\n          <button class=\"btn btn-ghost\" onclick=\"exportHistorialExcel()\" style=\"font-size:12px;height:32px;padding:0 12px\">\n            <svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><line x1=\"3\" y1=\"9\" x2=\"21\" y2=\"9\"/><line x1=\"3\" y1=\"15\" x2=\"21\" y2=\"15\"/><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"21\"/></svg>\n            Exportar Excel\n          </button>\n        </div>\n      </div>\n    </div>\n\n    <!-- ── Stats ── -->\n    <div class=\"hist-stats\">\n      <div class=\"hstat\">\n        <div class=\"hstat-label\">Total notas</div>\n        <div class=\"hstat-value\" id=\"statTotalNotas\">—</div>\n      </div>\n      <div class=\"hstat\">\n        <div class=\"hstat-label\">Clientes</div>\n        <div class=\"hstat-value\" id=\"statClientes\">—</div>\n      </div>\n      <div class=\"hstat\">\n        <div class=\"hstat-label\">Ingresos</div>\n        <div class=\"hstat-value\" id=\"statRevenue\" style=\"font-size:16px\">—</div>\n      </div>\n    </div>\n\n    <!-- ── Barra de selección masiva ── -->\n    <div class=\"bulk-bar\" id=\"bulkBarHist\">\n      <span class=\"bulk-count\" id=\"bulkCountHist\">0 seleccionadas</span>\n      <button class=\"btn-template\" onclick=\"exportSelectedExcel()\">\n        <svg viewBox=\"0 0 24 24\" width=\"13\" height=\"13\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><line x1=\"3\" y1=\"9\" x2=\"21\" y2=\"9\"/><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"21\"/></svg>\n        Exportar seleccionadas\n      </button>\n      <button class=\"btn-bulk-delete\" id=\"btnDeleteSelectedHist\" onclick=\"deleteSelectedHist()\">\n        <svg viewBox=\"0 0 24 24\" width=\"13\" height=\"13\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6\"/></svg>\n        Eliminar seleccionadas\n      </button>\n      <button class=\"btn-bulk-select-all\" onclick=\"selectAllHist()\">Seleccionar todo</button>\n    </div>\n\n    <!-- ── Tabla ── -->\n    <div class=\"table-wrap\">\n      <table>\n        <thead>\n          <tr>\n            <th class=\"col-check\"><input type=\"checkbox\" class=\"row-checkbox\" id=\"checkAllHist\" onchange=\"toggleAllHist(this)\"></th>\n            <th class=\"col-num\">N° Nota</th>\n            <th>Cliente</th>\n            <th class=\"col-vendedor\">Vendedor</th>\n            <th class=\"col-date\">Fecha</th>\n            <th class=\"col-total\">Total</th>\n            <th class=\"col-act\">Ver</th>\n          </tr>\n        </thead>\n        <tbody id=\"histBody\"></tbody>\n      </table>\n      <div class=\"empty-state\" id=\"emptyState\">\n        <svg class=\"empty-state-icon\" viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\n        <p>Sin registros que coincidan.</p>\n      </div>\n      <div class=\"table-footer\">\n        <span class=\"table-footer-text\" id=\"footerInfo\">Cargando…</span>\n      </div>\n    </div>\n  </div>\n</main>\n\n<!-- ── Modal: Ver nota completa (solo lectura) ── -->\n<div class=\"modal-overlay\" id=\"verModal\" onclick=\"outsideCloseVer(event)\">\n  <div class=\"modal\" style=\"max-width:520px\">\n    <div class=\"modal-header\">\n      <div>\n        <h2>Detalle de la nota</h2>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeVerModal()\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\" style=\"padding:18px\">\n      <div class=\"ver-modal-content\" style=\"padding:20px;border-radius:10px;border:1px solid var(--border)\">\n        <div class=\"print-header\">\n          <div>\n            <img src=\"data:image/png;base64,\" style=\"height:56px;display:block\" alt=\"Musical Fever\">\n            <div style=\"font-size:11px;color:#94a3b8;margin-top:6px\">Sistema de Gestión de Pedidos</div>\n          </div>\n          <div class=\"print-meta\">\n            <strong id=\"vNotaNum\">—</strong>\n            Fecha: <span id=\"vFecha\"></span> · <span id=\"vHora\"></span>\n          </div>\n        </div>\n        <div class=\"print-client-box\">\n          <div class=\"label\">Cliente</div>\n          <div class=\"val\" id=\"vNombre\">—</div>\n          <div class=\"ruc\">RUC: <span id=\"vRuc\">—</span></div>\n          <div class=\"ruc\" id=\"vVendedorRow\" style=\"display:none\">Vendedor: <span id=\"vVendedor\">—</span></div>\n        </div>\n        <table class=\"print-table\">\n          <thead>\n            <tr>\n              <th>Código</th>\n              <th>Producto</th>\n              <th class=\"right\">P. Unit.</th>\n              <th class=\"right\">Cant.</th>\n              <th class=\"right\">Desc. %</th>\n              <th class=\"right\">Subtotal</th>\n            </tr>\n          </thead>\n          <tbody id=\"vBody\"></tbody>\n        </table>\n        <div class=\"print-totals\" id=\"vTotals\"></div>\n      </div>\n    </div>\n    <div class=\"modal-footer ver-modal-footer\">\n      <button class=\"btn btn-ghost btn-sm\" onclick=\"closeVerModal()\">Cerrar</button>\n      <div class=\"ver-modal-actions\">\n        <button class=\"btn btn-ghost btn-icon-mobile\" id=\"btnDeleteNota\" style=\"color:var(--red);border-color:#FECACA\" onclick=\"deleteCurrentNota()\" title=\"Eliminar\">\n          <svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6\"/></svg>\n          <span class=\"btn-label\">Eliminar</span>\n        </button>\n        <button class=\"btn btn-ghost btn-icon-mobile\" id=\"btnEditNota\" onclick=\"editNota()\" title=\"Editar\">\n          <svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7\"/><path d=\"M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z\"/></svg>\n          <span class=\"btn-label\">Editar</span>\n        </button>\n        <button class=\"btn btn-ghost btn-icon-mobile\" id=\"btnShareNota\" onclick=\"shareNota()\" title=\"Compartir\">\n          <svg viewBox=\"0 0 24 24\"><circle cx=\"18\" cy=\"5\" r=\"3\"/><circle cx=\"6\" cy=\"12\" r=\"3\"/><circle cx=\"18\" cy=\"19\" r=\"3\"/><line x1=\"8.59\" y1=\"13.51\" x2=\"15.42\" y2=\"17.49\"/><line x1=\"15.41\" y1=\"6.51\" x2=\"8.59\" y2=\"10.49\"/></svg>\n          <span class=\"btn-label\">Compartir</span>\n        </button>\n        <div class=\"download-menu-wrap\">\n          <button class=\"btn btn-primary\" id=\"btnDownloadNota\" onclick=\"toggleDownloadMenu(event)\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\n            Descargar\n            <svg viewBox=\"0 0 24 24\" class=\"chev\"><polyline points=\"6 9 12 15 18 9\"/></svg>\n          </button>\n          <div class=\"download-menu\" id=\"downloadMenu\">\n            <button class=\"download-menu-item\" onclick=\"downloadNotaAs('pdf')\">PDF</button>\n            <button class=\"download-menu-item\" onclick=\"downloadNotaAs('excel')\">Excel</button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n\n\n<!-- ── Toast limpieza ── -->\n<div id=\"cleanupToast\"></div>\n\n<!-- ── Scripts ── -->\n",
  "nueva-nota": "<main class=\"main\">\n  <div class=\"topbar\">\n    <div class=\"topbar-title\">\n      <h1>Nueva Nota de Pedido</h1>\n      \n    </div>\n    <div class=\"topbar-actions\">\n      <span class=\"nota-number\" id=\"notaNumber\">NP-2025-008</span>\n      <button type=\"button\" class=\"btn btn-ghost\" onclick=\"goBackFromNota()\">\n        <svg viewBox=\"0 0 24 24\"><polyline points=\"15 18 9 12 15 6\"/></svg>\n        Volver\n      </button>\n    </div>\n  </div>\n\n  <div class=\"page-content\">\n    <div class=\"nota-layout\">\n\n      <!-- ── Left column ── -->\n      <div>\n        <!-- Client info -->\n        <div class=\"client-card\">\n          <div class=\"client-card-icon\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\"/><polyline points=\"9 22 9 12 15 12 15 22\"/></svg>\n          </div>\n          <div class=\"client-card-info\">\n            <div class=\"client-card-name\" id=\"displayNombre\">—</div>\n            <div class=\"client-card-ruc\">RUC: <span id=\"displayRuc\">—</span></div>\n          </div>\n        </div>\n\n        <!-- Add product bar -->\n        <div class=\"add-product-bar\">\n          <h3>Agregar artículo</h3>\n          <div class=\"add-product-grid\">\n            <div style=\"position:relative\">\n              <div class=\"add-input-label\">Producto</div>\n              <div class=\"product-input-wrap\">\n                <input class=\"form-input\" type=\"text\" id=\"productSearch\" placeholder=\"Buscar por nombre o código…\"\n                  autocomplete=\"off\"\n                  oninput=\"onProductSearchInput()\"\n                  onfocus=\"onProductSearchInput()\"\n                  onblur=\"onProductSearchBlur()\">\n                <button type=\"button\" class=\"product-search-clear\" id=\"productSearchClear\" style=\"display:none\" onmousedown=\"event.preventDefault()\" onclick=\"clearProductSearch()\" aria-label=\"Limpiar producto\" title=\"Limpiar\">\n                  <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n                </button>\n              </div>\n              <input type=\"hidden\" id=\"selectedProductCode\" value=\"\">\n              <div id=\"productSuggestions\" class=\"product-suggestions\" style=\"display:none\"></div>\n              <div class=\"stock-hint\" id=\"stockHint\" style=\"display:none\">\n                <svg viewBox=\"0 0 24 24\" width=\"11\" height=\"11\" stroke=\"currentColor\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z\"/></svg>\n                <span id=\"stockHintText\"></span>\n              </div>\n            </div>\n            <div>\n              <div class=\"add-input-label\">Cantidad</div>\n              <input class=\"form-input text-mono\" type=\"number\" id=\"addQty\" min=\"1\" value=\"1\" style=\"height:36px\">\n            </div>\n            <div>\n              <div class=\"add-input-label\">Precio unit.</div>\n              <input class=\"form-input text-mono\" type=\"number\" id=\"addPrice\" min=\"0\" step=\"0.01\" placeholder=\"0.00\" style=\"height:36px\">\n            </div>\n            <div>\n              <button class=\"btn btn-primary\" style=\"margin-top:20px\" onclick=\"addItem()\">\n                <svg viewBox=\"0 0 24 24\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg>\n                Añadir\n              </button>\n            </div>\n          </div>\n        </div>\n\n        <!-- Products list -->\n        <div class=\"products-section\">\n          <div class=\"products-section-header\">\n            <h3>Artículos del pedido</h3>\n            <span id=\"itemCount\">0</span>\n          </div>\n          <div id=\"emptyProducts\" class=\"empty-products\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z\"/><line x1=\"3\" y1=\"6\" x2=\"21\" y2=\"6\"/><path d=\"M16 10a4 4 0 0 1-8 0\"/></svg>\n            <p>Aún no hay artículos. Agrega un producto para comenzar.</p>\n          </div>\n          <table class=\"prod-table\" id=\"prodTable\" style=\"display:none\">\n            <thead>\n              <tr>\n                <th>Código</th>\n                <th>Producto</th>\n                <th class=\"right\">P. Unit.</th>\n                <th style=\"text-align:center;width:110px\">Cantidad</th>\n                <th class=\"right\" style=\"width:80px\">Desc. %</th>\n                <th class=\"right\">Subtotal</th>\n                <th style=\"width:36px\"></th>\n              </tr>\n            </thead>\n            <tbody id=\"prodBody\"></tbody>\n          </table>\n        </div>\n      </div>\n\n      <!-- ── Right column: summary ── -->\n      <div class=\"summary-card\">\n        <h3>Resumen del pedido</h3>\n\n        <div class=\"summary-row\">\n          <span>Subtotal</span>\n          <span class=\"summary-value\" id=\"sumSubtotal\">S/ 0.00</span>\n        </div>\n        <div class=\"summary-row\" id=\"discountRow\" style=\"display:none; color:var(--green)\">\n          <span>Descuento (<span id=\"discPctLabel\">0</span>%)</span>\n          <span class=\"summary-value\" id=\"sumDiscount\" style=\"color:var(--green)\">− S/ 0.00</span>\n        </div>\n        <div class=\"summary-row total\">\n          <span>Total</span>\n          <span class=\"summary-value\" id=\"sumTotal\">S/ 0.00</span>\n        </div>\n\n        <!-- Discount -->\n        <div class=\"discount-wrap\">\n          <label>Descuento</label>\n          <div class=\"discount-presets\">\n            <span class=\"disc-pill\" onclick=\"setDiscount(5,this)\">5%</span>\n            <span class=\"disc-pill\" onclick=\"setDiscount(10,this)\">10%</span>\n            <span class=\"disc-pill\" onclick=\"setDiscount(15,this)\">15%</span>\n            <span class=\"disc-pill\" onclick=\"setDiscount(20,this)\">20%</span>\n          </div>\n          <div class=\"discount-custom-row\">\n            <input type=\"number\" id=\"discInput\" min=\"0\" max=\"100\" step=\"0.5\" placeholder=\"0\"\n              oninput=\"onDiscountInput()\">\n            <span>%</span>\n          </div>\n          <div class=\"discount-saving\" id=\"discSaving\" style=\"display:none\"></div>\n        </div>\n\n\n        <div style=\"margin-top:14px\">\n          <button class=\"btn btn-primary\" style=\"width:100%;height:42px;font-size:14px;justify-content:center;font-weight:700;letter-spacing:-0.01em\" onclick=\"confirmOrder()\">\n            Confirmar pedido\n          </button>\n        </div>\n      </div>\n\n    </div>\n  </div>\n</main>\n",
  "registros": "<!-- ── Main: Registros (solo admin) ── -->\n<main class=\"main\">\n  <div class=\"topbar\">\n    <div class=\"topbar-title\">\n      <h1>Registros</h1>\n      <p>Cuentas del equipo — quién tiene acceso y con qué rol</p>\n    </div>\n    <div class=\"topbar-actions\">\n      <button class=\"btn btn-ghost btn-new-item\" onclick=\"openNewVendor()\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><line x1=\"19\" y1=\"8\" x2=\"19\" y2=\"14\"/><line x1=\"22\" y1=\"11\" x2=\"16\" y2=\"11\"/></svg>\n        Nuevo vendedor\n      </button>\n    </div>\n  </div>\n\n  <div class=\"page-content\">\n    <div class=\"table-wrap\">\n      <div class=\"table-footer table-footer-top\">\n        <span class=\"table-footer-text\" id=\"regFooterInfo\">Cargando…</span>\n      </div>\n      <table>\n        <thead>\n          <tr>\n            <th>Nombre</th>\n            <th>Usuario</th>\n            <th class=\"col-city\">Rol</th>\n            <th class=\"col-city\">Estado</th>\n            <th class=\"col-acts\"></th>\n          </tr>\n        </thead>\n        <tbody id=\"regTableBody\"></tbody>\n      </table>\n      <div class=\"empty-state\" id=\"regEmptyState\" style=\"display:none\">\n        <p>Todavía no hay vendedores registrados.</p>\n      </div>\n    </div>\n  </div>\n</main>\n\n<!-- Modal: nuevo vendedor -->\n<div class=\"modal-overlay\" id=\"newVendorOverlay\">\n  <div class=\"modal\" style=\"max-width:420px\">\n    <div class=\"modal-header\">\n      <div>\n        <h2>Nuevo vendedor</h2>\n        <p>Crea una cuenta individual — no se toca la sesión actual</p>\n      </div>\n      <button class=\"modal-close\" onclick=\"closeNewVendor()\">\n        <svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\">\n      <div class=\"form-group\">\n        <label class=\"form-label\">Nombre</label>\n        <input type=\"text\" id=\"newVendorNombre\" class=\"form-input\" placeholder=\"Ej. Ana Torres\" autocomplete=\"off\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Usuario (para iniciar sesión)</label>\n        <input type=\"text\" id=\"newVendorUsuario\" class=\"form-input\" placeholder=\"Ej. ana\" autocomplete=\"off\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Correo <span style=\"font-weight:400;color:var(--text-3)\">(opcional, solo de contacto)</span></label>\n        <input type=\"email\" id=\"newVendorEmail\" class=\"form-input\" placeholder=\"ana@fever.com\" autocomplete=\"off\">\n      </div>\n      <div class=\"form-group\">\n        <label class=\"form-label\">Contraseña temporal</label>\n        <input type=\"text\" id=\"newVendorPassword\" class=\"form-input\" placeholder=\"Mínimo 6 caracteres\" autocomplete=\"off\">\n      </div>\n      <p id=\"newVendorError\" class=\"dcm-subtitle\" style=\"color:var(--red);display:none\"></p>\n    </div>\n    <div class=\"modal-footer\">\n      <button class=\"btn btn-ghost\" onclick=\"closeNewVendor()\">Cancelar</button>\n      <button class=\"btn btn-primary\" id=\"newVendorSubmit\" onclick=\"submitNewVendor()\">Crear cuenta</button>\n    </div>\n  </div>\n</div>\n"
};

window.Router = (function() {
  const VIEWS = {
    stock:        { init: () => window.Stock       && Stock.init() },
    pedidos:      { init: () => window.Pedidos     && Pedidos.init() },
    historial:    { init: () => window.Historial   && Historial.init() },
    'nueva-nota': { init: (params) => window.NuevaNota && NuevaNota.init(params) },
    registros:    { init: () => window.Registros   && Registros.init() }
  };

  let currentPage = null;

  function setActiveNavItem(page) {
    document.querySelectorAll('.nav-item[data-page]').forEach(el => {
      el.classList.toggle('active', el.dataset.page === page);
    });
  }

  function go(page, opts) {
    opts = opts || {};
    const view = VIEWS[page];
    const html = VIEWS_HTML[page];

    if (!view || !html) {
      console.error('[Router] Página desconocida:', page);
      return;
    }

    if (page === currentPage && !opts.force) return;

    const root = document.getElementById('viewRoot');

    try {
      root.innerHTML = html;
      currentPage = page;
      setActiveNavItem(page);
      if (!opts.skipHistory) {
        history.pushState({ page }, '', '#' + page);
      }
      view.init(opts.params);
    } catch (err) {
      console.error('[Router] Error al mostrar la vista', page, err);
      root.innerHTML = '<div style="padding:40px;text-align:center;color:var(--text-3)">' +
        'Ocurrió un error al mostrar esta sección. <a href="#" onclick="Router.go(\'' + page + '\',{force:true});return false;">Reintentar</a>' +
        '</div>';
    }
  }

  function start() {
    const initialPage = (window.location.hash || '#pedidos').slice(1);
    go(initialPage, { skipHistory: true });

    window.addEventListener('popstate', e => {
      const page = (e.state && e.state.page) || (window.location.hash || '#pedidos').slice(1);
      go(page, { skipHistory: true });
    });
  }

  return { go, start, get currentPage() { return currentPage; } };
})();
